"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type ConstellationProps = {
  className?: string;
  label?: string;
  nodes?: number;
};

/**
 * Connecting-dots constellation loader for agent / network work.
 */
function Constellation({
  className,
  label = "Linking context",
  nodes = 5,
}: ConstellationProps) {
  const pts = React.useMemo(() => {
    const n = Math.min(8, Math.max(3, nodes));
    return Array.from({ length: n }, (_, i) => {
      const a = (-Math.PI / 2) + (Math.PI * 2 * i) / n;
      return { x: 50 + Math.cos(a) * 32, y: 50 + Math.sin(a) * 32 };
    });
  }, [nodes]);

  const path = pts
    .map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`)
    .join(" ");

  return (
    <div className={cn("inline-flex flex-col items-center gap-3", className)}>
      <svg viewBox="0 0 100 100" className="size-24 text-primary">
        <path
          d={`${path} Z`}
          fill="none"
          stroke="currentColor"
          strokeWidth="1.2"
          strokeDasharray="48"
          className="animate-[joy-weave_2.2s_ease-in-out_infinite] opacity-70"
        />
        {pts.map((p, i) => (
          <circle
            key={i}
            cx={p.x}
            cy={p.y}
            r="3.2"
            className="fill-primary"
            style={{
              animation: `joy-pulse-soft 2s ease-in-out ${i * 0.15}s infinite`,
            }}
          />
        ))}
        <circle cx="50" cy="50" r="4" className="fill-foreground/80" />
      </svg>
      <div className="text-xs font-medium text-muted-foreground">{label}</div>
    </div>
  );
}

export { Constellation };
